Given a string s, find the smallest window length that contains all the characters of the given string at least one time.Examples:Input: s = "aabcbcdbca"Output: 4Explanation: Sub-String "dbca" has the smallest length that contains all the characters of string s.Input: s = "aaab"Output: 2Explanation: Sub-String "ab" has the smallest length that contains all the characters of string s.Input: s = "geeksforgeeks"Output: 7Explanation: There are multiple substring with smallest length that contains all characters of string s, "eksforg" and "ksforge".Try It YourselfTable of Content[Naive Approach] Generating All Substrings - O(n ^ 2) Time and O(1) Space[Expected Approach] Using Sliding Window - O(n) Time and O(1) Space[Naive Approach] Generating All Substrings - O(n ^ 2) Time and O(1) SpaceThe idea is to try every possible starting position and expand the window towards the right. For each window, keep track of the distinct characters present in it. As soon as the window contains all distinct characters of the string, update the minimum length. Store all distinct characters of s in visited array.For every starting index i, create a cur array for the current window. Expand the window from i and mark each character in cur. When cur contains all characters in visited, update ans and stop.
            C++

    #include <bits/stdc++.h>
using namespace std;

int findSubString(string &s)
{
    int n = s.size();

    // Initially, the answer can be the whole string
    int ans = n;

    // Store all distinct characters present in the string
    vector<bool> visited(26, false);

    for (int i = 0; i < n; i++)
    {
        visited[s[i] - 'a'] = true;
    }

    // Try every possible starting position
    for (int i = 0; i < n; i++)
    {
        vector<bool> cur(26, false);

        // Expand the window from i to the right
        for (int j = i; j < n; j++)
        {
            cur[s[j] - 'a'] = true;

            // If the current window contains all distinct characters
            if (cur == visited)
            {
                ans = min(ans, j - i + 1);
                break;
            }
        }
    }

    return ans;
}

int main()
{
    string s = "aabcbcdbca";
    cout << findSubString(s) << endl;

    return 0;
}


