            bool[] cur = new bool[26];

            // Expand the window from i to the right
            for (int j = i; j < n; j++) {
                cur[s[j] - 'a'] = true;

                // If the current window contains all
                // distinct characters
                if (AreEqual(cur, visited)) {
                    ans = Math.Min(ans, j - i + 1);
                    break;
                }
            }
        }

        return ans;
