    #include <iostream>
using namespace std;

int findSubString(string &s)
{
    int n = s.size();

    // to store all distinct characters
    vector<bool> visited(26, false);
    int distinct = 0;

    for (int i = 0; i < n; i++)
    {
        if (visited[s[i] - 'a'] == false)
        {
            visited[s[i] - 'a'] = true;
            distinct++;
        }
    }

    // to store the visited of characters
    // in the current window
    vector<int> cur(26, 0);
    int cnt = 0;

    int ans = n;
    int start = 0;
    for (int i = 0; i < n; i++)
    {
        // Count characters in the current
        // window
        cur[s[i] - 'a']++;
        if (cur[s[i] - 'a'] == 1)
        {
            cnt++;
        }

        // If the count becomes same as overall
        while (cnt == distinct)
        {
            ans = min(ans, i - start + 1);

            // Remove characters from left
            cur[s[start] - 'a']--;
            if (cur[s[start] - 'a'] == 0)
            {
                cnt--;
            }
            start++;
        }
    }
    return ans;
}

int main()
{
    string s = "aabcbcdbca";
    cout << findSubString(s) << endl;

    return 0;
}


